<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>K-Touch | Inventory Management</title>
  <style>
    :root{--teal:#07968e;--teal2:#12a79d;--cyan:#27acd0;--ink:#10172a;--muted:#667085;--line:#dce6e9;--bg:#f3faf8;--blue:#087bf2}
    *{box-sizing:border-box} body{margin:0;color:var(--ink);background:var(--bg);font:12px/1.4 Arial,Helvetica,sans-serif} button,input,select{font:inherit}
    .top{height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;background:#fff;border-bottom:1px solid #edf1f2}
    .logo{display:flex;align-items:center;gap:10px}.logo-word{font-size:28px;letter-spacing:-2px}.logo-word b:nth-child(1){color:#f36b21}.logo-word b:nth-child(2){color:#159d92}.logo small{padding-left:10px;border-left:1px solid #aaa;line-height:1.05;color:#333}
    .admin{display:flex;align-items:center;gap:8px}.avatar{width:35px;height:35px;display:grid;place-items:center;border-radius:50%;background:#ffd800;font-size:19px}
    .nav{height:44px;display:flex;align-items:center;gap:31px;padding:0 24px;color:#fff;background:linear-gradient(90deg,#2fb1d0,#20a8c6);white-space:nowrap;overflow:auto}
    .nav span{display:flex;gap:7px;align-items:center;font-size:11px;font-weight:700}
    main{padding:18px 20px 30px}.hero{position:relative;z-index:4;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:15px 18px;background:rgba(255,255,255,.84);border:1px solid #e4efed;border-radius:11px;box-shadow:0 5px 18px rgba(29,91,85,.05)}
    .kicker{color:#087f78;font-size:10px;font-weight:900;letter-spacing:.08em}.hero h1{margin:2px 0 0;font-size:22px}.hero p{margin:3px 0 0;color:#65727a;font-size:11px}
    .hero-actions{display:flex;align-items:center;gap:8px}.drop{position:relative}.hero-btn{height:35px;padding:0 13px;border:1px solid #149d95;border-radius:6px;color:#087f78;background:#fff;font-weight:800;cursor:pointer}.hero-btn.primary{color:#fff;background:#079c93}.soft{border:0;color:#225dcc;background:#eaf1ff}.purple{color:#7431d2;background:#f0e9ff}
    .menu{position:absolute;top:41px;right:0;z-index:10;display:none;width:205px;margin:0;padding:6px 0;list-style:none;background:#fff;border:1px solid #dbe5e7;border-radius:8px;box-shadow:0 14px 30px rgba(23,67,65,.16)}.drop.open .menu{display:block}.menu button{width:100%;display:flex;gap:9px;align-items:center;padding:9px 13px;border:0;color:#17213a;background:none;text-align:left;font-weight:700;cursor:pointer}.menu button:hover{color:#087f78;background:#effaf8}.menu i{width:15px;color:#1eacc6;font-style:normal;text-align:center}
    .stats{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:12px;margin:16px 0}.stat{position:relative;min-height:108px;padding:15px;background:#fff;border:1px solid #e8eeee;border-radius:9px;box-shadow:0 5px 15px rgba(23,67,65,.06);overflow:hidden}.stat:after{position:absolute;left:13px;right:13px;bottom:10px;height:3px;background:var(--c);content:""}.stat small{color:#65727a;font-size:10px;font-weight:800}.stat strong{display:block;margin:7px 0 3px;color:var(--c);font-size:25px;line-height:1}.stat span{color:#7f8a91;font-size:10px}.stat-icon{position:absolute;right:14px;top:16px;width:42px;height:42px;display:grid;place-items:center;border-radius:9px;color:var(--c);background:color-mix(in srgb,var(--c) 9%,white);font-size:20px}
    .workspace{display:grid;grid-template-columns:275px minmax(0,1fr);gap:16px;align-items:start}.card{background:#fff;border:1px solid #e0eaeb;border-radius:9px;box-shadow:0 5px 18px rgba(23,67,65,.07);overflow:hidden}.card-head{display:flex;align-items:center;justify-content:space-between;min-height:56px;padding:10px 14px;color:#fff;background:linear-gradient(90deg,#078f88,#0ba89e)}.card-head h2{margin:0;font-size:15px}.filter-body{padding:15px}.filter-body>p{margin:0 0 20px;color:#728087;font-size:10px}.field{margin-bottom:15px}.field label{display:block;margin-bottom:7px;font-size:11px;font-weight:800}.field select{width:100%;height:37px;padding:0 12px;color:#4c5961;background:#fff;border:1px solid #cfdadd;border-radius:7px;outline:none}.filter-buttons{display:grid;grid-template-columns:1fr 1fr;gap:10px}.btn{height:37px;border:1px solid #9eabb4;border-radius:6px;background:#fff;font-weight:800;cursor:pointer}.btn.apply{color:#fff;border-color:#087bf2;background:#087bf2}
    .items{min-width:0}.items-head-actions{display:flex;gap:8px}.action{height:35px;padding:0 16px;border:1px solid #fff;border-radius:6px;color:#087b7a;background:#fff;font-weight:800;cursor:pointer}.action.add{color:#fff;background:transparent}.badge-count{display:inline-block;margin-top:6px;padding:6px 11px;border-radius:5px;color:#086a76;background:#e9fbff;font-weight:800}
    .toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px}.toolbar-left{display:flex;align-items:center;gap:10px}.toolbar select,.toolbar input{height:35px;border:1px solid #cfdadd;border-radius:6px;background:#fff}.toolbar select{padding:0 12px}.toolbar input{width:220px;padding:0 11px}.table-wrap{overflow-x:auto;border-top:1px solid #e7ecee}.inventory{width:100%;min-width:1420px;border-collapse:collapse}.inventory th{height:40px;padding:7px 8px;color:#fff;background:#087f78;border-right:1px solid rgba(255,255,255,.14);font-size:9px;text-align:left;white-space:nowrap}.inventory td{height:55px;padding:8px;border-right:1px solid #e2e8ea;border-bottom:1px solid #d8e0e2;font-size:10px;white-space:nowrap}.inventory tbody tr:nth-child(even){background:#f5f6f7}.inventory tbody tr:hover{background:#eefaf8}.name{white-space:normal!important;font-weight:700}.inline{display:inline-flex;align-items:center;gap:5px}.mini-edit,.more{width:24px;height:24px;border:1px solid #9caeb8;border-radius:6px;color:#436375;background:#fff;cursor:pointer}.more{width:30px;color:#0648ad;border-color:#2582ee;font-weight:900}.pill{display:inline-flex;align-items:center;justify-content:center;min-height:24px;padding:3px 7px;border:1px solid currentColor;border-radius:5px;background:#fff;font-size:9px;font-weight:800}.green{color:#139642;background:#f2fff5}.red{color:#ff4242;background:#fff5f5}.amber{color:#f08a00;background:#fff9ef}.coral{color:#ff4949;background:#fff6f6}.cyan{color:#079ab9;background:#f2fcff}.footer{display:flex;align-items:center;justify-content:space-between;padding:13px 14px}.pages{display:flex;gap:6px}.page{min-width:34px;height:34px;border:1px solid #d2dade;border-radius:6px;background:#fff;cursor:pointer}.page.active{color:#fff;border-color:#087bf2;background:#087bf2}
    .modal-backdrop{position:fixed;inset:0;z-index:100;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(11,27,35,.52);backdrop-filter:blur(2px)}.modal-backdrop.show{display:flex}.item-modal{width:min(760px,100%);max-height:calc(100vh - 40px);overflow:auto;background:#f7fafb;border:1px solid #dce7e9;border-radius:12px;box-shadow:0 24px 70px rgba(7,40,43,.28)}
    .modal-head{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:16px 18px;color:#fff;background:linear-gradient(90deg,#078f88,#0aa89d)}.modal-title{display:flex;align-items:center;gap:11px}.modal-title-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:8px;color:#087d76;background:#e7fffb;font-size:18px}.modal-title h2{margin:0;font-size:17px}.modal-title p{margin:2px 0 0;color:#dcfffb;font-size:10px}.modal-x{width:33px;height:33px;border:1px solid rgba(255,255,255,.6);border-radius:7px;color:#fff;background:transparent;font-size:20px;cursor:pointer}
    .modal-body{display:grid;gap:12px;padding:15px}.form-section{padding:15px;background:#fff;border:1px solid #dde7e9;border-radius:9px;box-shadow:0 3px 10px rgba(23,67,65,.04)}.section-title{display:flex;align-items:center;gap:8px;margin:0 0 13px;padding-bottom:9px;color:#087f78;border-bottom:1px solid #e6eeee;font-size:12px;font-weight:900;text-transform:uppercase}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.form-grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.modal-field label{display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;color:#20293b;font-size:10px;font-weight:800}.required{color:#f04b4b}.control-wrap{display:flex;gap:6px}.modal-field input,.modal-field select{width:100%;height:38px;padding:0 11px;color:#40505a;background:#fff;border:1px solid #ccd9dc;border-radius:7px;outline:none}.modal-field input:focus,.modal-field select:focus{border-color:#0ca69c;box-shadow:0 0 0 3px rgba(12,166,156,.11)}.add-inline{flex:0 0 38px;height:38px;border:1px solid #159d92;border-radius:7px;color:#fff;background:#159d92;font-size:18px;cursor:pointer}.help{display:block;margin-top:5px;color:#869198;font-size:9px}.toggle-row{display:flex;align-items:center;justify-content:space-between;min-height:45px;padding:8px 10px;border:1px solid #dce5e7;border-radius:7px;background:#fbfdfd}.toggle-copy b{display:block;font-size:10px}.toggle-copy span{color:#7a878e;font-size:9px}.switch{position:relative;width:38px;height:21px}.switch input{opacity:0;width:0;height:0}.slider{position:absolute;inset:0;border-radius:999px;background:#cbd4d7;cursor:pointer;transition:.2s}.slider:before{position:absolute;left:3px;top:3px;width:15px;height:15px;border-radius:50%;background:#fff;content:"";transition:.2s}.switch input:checked+.slider{background:#159d92}.switch input:checked+.slider:before{transform:translateX(17px)}
    .modal-foot{position:sticky;bottom:0;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 15px;background:#fff;border-top:1px solid #dce6e8}.foot-note{color:#75838a;font-size:9px}.modal-buttons{display:flex;gap:8px}.modal-button{height:36px;padding:0 16px;border:1px solid #aebbc1;border-radius:7px;color:#43515a;background:#fff;font-weight:800;cursor:pointer}.modal-button.save{color:#fff;border-color:#159d92;background:#159d92}
    @media(max-width:1100px){.stats{grid-template-columns:repeat(3,1fr)}.nav{gap:18px}.hero{align-items:flex-start;flex-direction:column}.hero-actions{flex-wrap:wrap}}
    @media(max-width:760px){main{padding:10px}.workspace{display:block}.filter-card{margin-bottom:12px}.stats{grid-template-columns:repeat(2,1fr)}.toolbar{align-items:flex-start;flex-direction:column}.toolbar input{width:100%}.nav{padding:0 12px}.items-head-actions{flex-wrap:wrap}.top{padding:0 12px}.form-grid,.form-grid.two{grid-template-columns:1fr}.modal-backdrop{padding:8px}.item-modal{max-height:calc(100vh - 16px)}}
  </style>
</head>
<body>
  <header class="top"><div class="logo"><div class="logo-word"><b>K·</b><b>TOUCH</b></div><small>Point<br>of<br>Sale</small></div><div class="admin"><span class="avatar">😎</span><span>admin⌄</span></div></header>
  <nav class="nav"><span>▦ Dashboard</span><span>♟ Administration</span><span>▥ Inventory Manager</span><span>▰ Purchase Manager</span><span>▤ Store Manager</span><span>▰ Production Manager</span><span>$ Finance Manager</span><span>◔ Reports</span><span>☷ Task Board</span><span>⚙ Settings</span><span>⚑ Training</span><span>✉ Communication</span></nav>
  <main>
    <section class="hero">
      <div><div class="kicker">OPERATIONS</div><h1>♜ Inventory Management</h1><p>Manage the product catalogue, attributes, variants, and inventory setup from one workspace.</p></div>
      <div class="hero-actions">
        <div class="drop"><button class="hero-btn drop-toggle">◉ Catalogue⌄</button><ul class="menu"><li><button><i>♜</i>Master Inventory</button></li><li><button><i>◆</i>Master Attributes</button></li><li><button><i>▤</i>Attribute Options</button></li><li><button><i>▰</i>Units of Measure</button></li><li><button><i>▱</i>Stock Variants</button></li><li><button><i>☷</i>Inventory Settings</button></li></ul></div>
        <div class="drop"><button class="hero-btn primary drop-toggle">＋ Quick Add⌄</button><ul class="menu"><li><button data-open-item-modal>⊕ New Product</button></li><li><button>▣ New Category</button></li><li><button>♜ New Subcategory</button></li><li><button>▥ New Department</button></li><li><button>⚙ New Attribute</button></li><li><button>⊞ Merge Items</button></li><li><button>▱ New Variant</button></li></ul></div>
        <button class="hero-btn soft">▱ Variants</button><button class="hero-btn purple">☷ Settings</button>
      </div>
    </section>
    <section class="stats">
      <div class="stat" style="--c:#078f88"><small>ITEMS</small><strong>27</strong><span>active products</span><b class="stat-icon">♜</b></div>
      <div class="stat" style="--c:#087bf2"><small>CATEGORIES</small><strong>10</strong><span>item categories</span><b class="stat-icon">▤</b></div>
      <div class="stat" style="--c:#8b19ef"><small>SUBCATEGORIES</small><strong>26</strong><span>subcategories</span><b class="stat-icon">◆</b></div>
      <div class="stat" style="--c:#f07800"><small>DEPARTMENTS</small><strong>2</strong><span>item departments</span><b class="stat-icon">▥</b></div>
      <div class="stat" style="--c:#119b32"><small>UOM</small><strong>4</strong><span>active UOMs</span><b class="stat-icon">▰</b></div>
      <div class="stat" style="--c:#0794b4"><small>VARIANTS</small><strong>52</strong><span>stock variants</span><b class="stat-icon">▱</b></div>
    </section>
    <section class="workspace">
      <aside class="card filter-card"><div class="card-head"><h2>▼ Filter Inventory</h2></div><div class="filter-body"><p>Narrow the item list by department, category, subcategory, or product type.</p><div class="field"><label>Department</label><select id="department"><option value="">Search or select department…</option><option>BAR</option><option>KITCHEN</option></select></div><div class="field"><label>Category</label><select id="category"><option value="">Search or select category…</option><option>BEER</option><option>SPIRITS</option></select></div><div class="field"><label>Subcategory</label><select id="subcategory"><option value="">Search or select subcategory…</option><option>LOCAL</option><option>INTERNATIONAL</option></select></div><div class="field"><label>Product Type</label><select id="productType"><option value="">Search or select product type…</option><option>Inventory</option><option>Service</option></select></div><div class="filter-buttons"><button class="btn apply" id="apply">⌕ &nbsp; Apply</button><button class="btn" id="reset">↶ &nbsp; Reset</button></div></div></aside>
      <section class="card items"><div class="card-head"><div><h2>♜ Inventory Items</h2><span class="badge-count"><span id="count">6</span> active items</span></div><div class="items-head-actions"><button class="action">↥ &nbsp; Import</button><button class="action">↧ &nbsp; Export</button><button class="action add" data-open-item-modal>＋ Add New Item</button></div></div>
        <div class="toolbar"><div class="toolbar-left"><select><option>Bulk actions</option><option>Change Category</option><option>Change Subcategory</option><option>Discontinue</option></select><select><option>10</option><option>25</option><option>50</option></select><span>entries</span></div><label>Search: <input id="search" placeholder="Search items…"></label></div>
        <div class="table-wrap"><table class="inventory"><thead><tr><th><input type="checkbox" id="checkAll"></th><th>Item ID ↕</th><th>Name ↕</th><th>Category ↕</th><th>Subcategory ↕</th><th>Department ↕</th><th>Buying Price ↕</th><th>Price ↕</th><th>Happy Hour ↕</th><th>Menu Item ↕</th><th>Decimal ↕</th><th>Stock ↕</th><th>Recipe ↕</th><th>Portioning ↕</th><th>Tots ↕</th><th>Stock Type ↕</th><th>Tax ↕</th><th>Actions ↕</th></tr></thead><tbody id="rows"></tbody></table></div>
        <div class="footer"><span>Showing 1 to <span id="visible">6</span> of 27 entries</span><div class="pages"><button class="page">Previous</button><button class="page active">1</button><button class="page">2</button><button class="page">3</button><button class="page">Next</button></div></div>
      </section>
    </section>
  </main>
  <div class="modal-backdrop" id="itemModal" role="dialog" aria-modal="true" aria-labelledby="itemModalTitle">
    <form class="item-modal" id="itemForm">
      <header class="modal-head"><div class="modal-title"><span class="modal-title-icon">＋</span><div><h2 id="itemModalTitle">Quick Add Item</h2><p>Create a product and configure its menu settings.</p></div></div><button type="button" class="modal-x" data-close-item-modal aria-label="Close">×</button></header>
      <div class="modal-body">
        <section class="form-section"><h3 class="section-title">▤ Item Details</h3><div class="form-grid">
          <div class="modal-field"><label for="itemName">Item Name <span class="required">Required</span></label><input id="itemName" name="item_name" placeholder="Enter the item name" required><small class="help">Use the name customers and staff recognize.</small></div>
          <div class="modal-field"><label for="itemCategory">Category</label><div class="control-wrap"><select id="itemCategory" name="category"><option value="">Select category…</option><option>BEER</option><option>SPIRITS</option><option>SOFT DRINKS</option></select><button type="button" class="add-inline" title="Add category">＋</button></div></div>
          <div class="modal-field"><label for="itemSubcategory">Subcategory</label><div class="control-wrap"><select id="itemSubcategory" name="subcategory"><option value="">Select subcategory…</option><option>LOCAL</option><option>INTERNATIONAL</option><option>CAN</option></select><button type="button" class="add-inline" title="Add subcategory">＋</button></div></div>
          <div class="modal-field"><label for="itemDepartment">Department</label><select id="itemDepartment" name="department"><option value="">Select department…</option><option>BAR</option><option>KITCHEN</option></select></div>
          <div class="modal-field"><label for="productTypeModal">Product Type</label><select id="productTypeModal" name="product_type"><option value="">Select product type…</option><option>Inventory</option><option>Non Inventory</option><option>Service</option></select></div>
          <div class="modal-field"><label for="unit">Unit of Measure</label><select id="unit" name="unit"><option value="">Select unit…</option><option>Units</option><option>Litres</option><option>Kilograms</option></select></div>
        </div></section>
        <section class="form-section"><h3 class="section-title">$ Pricing &amp; Tax</h3><div class="form-grid">
          <div class="modal-field"><label for="buyingPrice">Buying Price</label><input id="buyingPrice" name="buying_price" type="number" min="0" step="0.01" placeholder="0.00"></div>
          <div class="modal-field"><label for="sellingPrice">Selling Price <span class="required">Required</span></label><input id="sellingPrice" name="selling_price" type="number" min="0" step="0.01" placeholder="0.00" required></div>
          <div class="modal-field"><label for="tax">Tax</label><select id="tax" name="tax"><option value="">Select tax…</option><option>VAT 16%</option><option>VAT 8%</option><option>Zero Rated</option></select></div>
        </div></section>
        <section class="form-section"><h3 class="section-title">⚙ Product Settings</h3><div class="form-grid two">
          <div class="toggle-row"><div class="toggle-copy"><b>Show on menu</b><span>Make this item available on the POS menu.</span></div><label class="switch"><input type="checkbox" name="menu_item" checked><span class="slider"></span></label></div>
          <div class="toggle-row"><div class="toggle-copy"><b>Track inventory</b><span>Reduce stock when this item is sold.</span></div><label class="switch"><input type="checkbox" name="track_stock" checked><span class="slider"></span></label></div>
          <div class="toggle-row"><div class="toggle-copy"><b>Allow decimals</b><span>Allow fractional quantities for this item.</span></div><label class="switch"><input type="checkbox" name="decimal"><span class="slider"></span></label></div>
          <div class="toggle-row"><div class="toggle-copy"><b>Happy hour pricing</b><span>Enable a separate promotional price.</span></div><label class="switch"><input type="checkbox" name="happy_hour"><span class="slider"></span></label></div>
        </div></section>
      </div>
      <footer class="modal-foot"><span class="foot-note"><span class="required">*</span> Complete the required fields before saving.</span><div class="modal-buttons"><button type="button" class="modal-button" data-close-item-modal>Cancel</button><button type="submit" class="modal-button save">✓ Save Item</button></div></footer>
    </form>
  </div>
  <script>
    const data=[['ITM-0001','GUINNESS KUBWA','BEER','LOCAL','BAR','0.00','400.00','Yes'],['ITM-0002','TUSKER LAGER','BEER','LOCAL','BAR','145.00','400.00','Yes'],['ITM-0003','PILSNER LAGER','BEER','LOCAL','BAR','145.00','400.00','Yes'],['ITM-0004','BLACK ICE','BEER','LOCAL','BAR','145.00','400.00','Yes'],['ITM-0005','WHITE CAP LIGHT','BEER','LOCAL','BAR','145.00','400.00','No'],['ITM-0006','TUSKER MALT','BEER','LOCAL','BAR','145.00','400.00','Yes']];
    const tbody=document.querySelector('#rows');
    function render(list=data){tbody.innerHTML=list.map(r=>`<tr><td><input type="checkbox" class="row-check"></td><td>${r[0]}</td><td class="name">${r[1]}</td><td><span class="inline">${r[2]} <button class="mini-edit" title="Change category">✎</button></span></td><td><span class="inline">${r[3]} <button class="mini-edit" title="Change subcategory">✎</button></span></td><td><span class="pill amber">${r[4]}</span></td><td>${r[5]}</td><td>${r[6]}</td><td><span class="pill ${r[7]==='No'?'red':'green'}">${r[7]}</span></td><td><span class="pill green">Yes</span></td><td><span class="pill green">Yes</span></td><td><span class="pill amber">Inventory</span></td><td><button class="pill coral">⚑ Set Recipe</button></td><td><button class="pill amber">↕ Set Portion</button></td><td><button class="pill amber">⌛ 0h 30s</button></td><td><button class="pill cyan">Units</button></td><td><button class="pill cyan">Set VAT</button></td><td><button class="more">•••</button></td></tr>`).join('');document.querySelector('#visible').textContent=list.length;document.querySelector('#count').textContent=list.length}
    render();
    document.querySelectorAll('.drop-toggle').forEach(btn=>btn.onclick=e=>{e.stopPropagation();const d=btn.parentElement;document.querySelectorAll('.drop.open').forEach(x=>x!==d&&x.classList.remove('open'));d.classList.toggle('open')});document.addEventListener('click',()=>document.querySelectorAll('.drop.open').forEach(x=>x.classList.remove('open')));
    document.querySelector('#search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();render(data.filter(r=>r.join(' ').toLowerCase().includes(q)))});
    document.querySelector('#apply').onclick=()=>{const vals=['department','category','subcategory'].map(id=>document.querySelector('#'+id).value);render(data.filter(r=>(!vals[0]||r[4]===vals[0])&&(!vals[1]||r[2]===vals[1])&&(!vals[2]||r[3]===vals[2])))};
    document.querySelector('#reset').onclick=()=>{document.querySelectorAll('.filter-body select').forEach(s=>s.value='');document.querySelector('#search').value='';render()};
    document.querySelector('#checkAll').onchange=e=>document.querySelectorAll('.row-check').forEach(c=>c.checked=e.target.checked);
    const itemModal=document.querySelector('#itemModal');
    const itemForm=document.querySelector('#itemForm');
    const openItemModal=()=>{document.querySelectorAll('.drop.open').forEach(x=>x.classList.remove('open'));itemModal.classList.add('show');document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('#itemName').focus(),0)};
    const closeItemModal=()=>{itemModal.classList.remove('show');document.body.style.overflow=''};
    document.querySelectorAll('[data-open-item-modal]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openItemModal()}));
    document.querySelectorAll('[data-close-item-modal]').forEach(button=>button.addEventListener('click',closeItemModal));
    itemModal.addEventListener('click',event=>{if(event.target===itemModal)closeItemModal()});
    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&itemModal.classList.contains('show'))closeItemModal()});
    itemForm.addEventListener('submit',event=>{event.preventDefault();if(!itemForm.reportValidity())return;closeItemModal();itemForm.reset()});
  </script>
</body>
</html>